document.querySelectorAll('[data-lab="CP01-I1"]').forEach(root=>{
const z=root.dataset.lang==='zh',f=k=>root.querySelector('[data-field="'+k+'"]');
const text=(x,y,s,size=22)=>'<text x="'+x+'" y="'+y+'" font-size="'+size+'">'+s+'</text>';
function draw(){let N=+f('segments').value,h=+f('bias').value,p=1/(1+Math.exp(-2*h)),vals=[],choose=1,total=0,mean=0,second=0;for(let j=0;j<=N;j++){if(j)choose*= (N-j+1)/j;let P=choose*Math.pow(p,j)*Math.pow(1-p,N-j),m=2*j-N;vals.push({P,m});total+=P;mean+=P*m;second+=P*m*m;}let sd=Math.sqrt(Math.max(0,second-mean*mean)),top=Math.ceil(Math.max(...vals.map(v=>v.P))*5)/5;f('nv').textContent=N;f('hv').textContent=h.toFixed(2);let X=r=>65+(r+1)*245,Y=P=>420-310*P/top,s='<g font-family="Arial,sans-serif" fill="#173e45">'+text(30,38,z?'末端位置的概率':'Probability of endpoint position',25);s+='<line x1="65" y1="420" x2="555" y2="420" stroke="#8ba1a3" stroke-width="2"/><line x1="65" y1="420" x2="65" y2="95" stroke="#8ba1a3" stroke-width="2"/>';for(const v of vals)s+='<rect x="'+(X(v.m/N)-Math.min(18,190/N))+'" y="'+Y(v.P)+'" width="'+Math.min(36,380/N)+'" height="'+(420-Y(v.P))+'" fill="#207d80"/>';s+='<line x1="'+X(mean/N)+'" y1="95" x2="'+X(mean/N)+'" y2="420" stroke="#bb6a38" stroke-width="3"/>';for(const r of [-1,-.5,0,.5,1])s+=text(X(r)-14,458,''+r,21);for(const P of [0,top/2,top])s+=text(10,Y(P)+7,P.toFixed(2),21);s+=text(20,85,'P')+text(445,505,'R / (Nb)',24)+text(30,550,z?'概率总和 = '+total.toFixed(6):'Total probability = '+total.toFixed(6),22)+'</g>';f('plot').innerHTML=s;
let force=h*4.141947;f('feedback').textContent=z?'向右概率 '+p.toFixed(6)+'；外力 '+force.toFixed(3)+' pN。平均末端位移 '+mean.toFixed(3)+' nm，标准差 '+sd.toFixed(3)+' nm，轮廓长度 '+N+' nm。':'Rightward probability '+p.toFixed(6)+'; force '+force.toFixed(3)+' pN. Mean endpoint displacement '+mean.toFixed(3)+' nm, standard deviation '+sd.toFixed(3)+' nm, contour length '+N+' nm.';}
['segments','bias'].forEach(k=>f(k).addEventListener('input',draw));draw();
});
